-- ============================================================================================================
-- 润石工作室官网 · 全套测试数据（演示 / 联调环境专用）
-- ============================================================================================================
--
-- ⚠️ 执行前必读
--   1. 本脚本是「重置型」种子脚本：会清空除刷题题库（studio_quiz_question 中已有的历史题目）之外的
--      全部业务数据，再写入一套前后关联、状态齐全的演示数据。**不要在生产库执行。**
--   2. 脚本不执行任何 DDL，只做 DELETE + INSERT；所有语句包在一个事务里，出错会整体回滚。
--   3. 题库中已存在的 447 道《中国近现代史纲要》题目会保留；本脚本只新增 12 道 Java / Vue 测试题。
--   4. 图片字段使用远程演示图（text_to_image 接口），不依赖本地上传目录；正式使用时可在后台替换为
--      通过「上传图片」得到的 /uploads/... 路径。
--
-- 执行方式（任选其一，建议带 utf8mb4 参数）：
--   mysql -uroot -p --default-character-set=utf8mb4 < db/test-data-full.sql
--   mysql> source db/test-data-full.sql
--
-- ============================================================================================================
-- 一、本脚本创建了哪些账号（README 级速查）
-- ============================================================================================================
--   管理员：shaoshing / shaoshing666      （角色 admin，同时绑定成员档案「邵兴」，可发帖/签到）
--   成员：  chenyu / 12345678             （陈宇，tech_lead）
--           linxia / 12345678             （林夏，tech_lead）
--           zhaoyang / 12345678           （赵阳，member）
--           wangmeng / 12345678           （王蒙，member）
--           liuqing / 12345678            （刘青，member）
--           sunhao / 12345678             （孙浩，member）
--           alumnus / 12345678            （李然，已毕业成员，member_status=1）
--   普通用户：tangke / zhouran / xuyi / 12345678（无成员档案，只能浏览、评论、点赞、刷题）
--   封禁用户：banned01 / 12345678         （user_status=1，用于验证登录封禁提示）
--
-- 密码哈希由项目同款 Hutool BCrypt 生成（$2a$10$...，60 位），可直接被 PasswordUtils.matches 校验。
--
-- ============================================================================================================
-- 二、数据覆盖面（每张表都有数据，且状态值覆盖完整枚举）
-- ============================================================================================================
--   sys_user                     12 个账号：admin / member / user / 封禁
--   studio_member                10 份档案：队长 / 组长 / 成员 / 已毕业 / 无账号的历史档案
--   studio_certificate           8 张证书：国家级/省级/校级 × 竞赛/软著/专利/论文
--   studio_member_certificate    14 条成员-证书关联
--   studio_project               6 个项目：已上线 / 研发中 / 已结题
--   studio_member_project        18 条成员-项目关联（队长一定在关联里）
--   studio_ai_session            4 个会话
--   studio_ai_message            12 条问答消息
--   studio_knowledge_doc         5 篇文档：已索引 / 待处理 / 失败
--   studio_knowledge_chunk       6 个切分块（与 doc.chunk_count 对齐）
--   studio_attendance            近 16 天工作日的签到记录（约 80 条，含内外网与请假缺勤）
--   studio_post                  12 篇帖子：已通过 / 待审 / 已驳回，AI 审核 5 种状态全覆盖
--   studio_post_comment          22 条评论：已通过 / 待审 / 已驳回，含楼中楼与楼层号
--   studio_post_report           4 条举报：待处理 / 已处置 / 举报不成立
--   studio_post_like             57 条点赞（与帖子的 like_count 严格对齐）
--   studio_page_visit            近 30 天 × 每天 8 次访问，共 240 条（够画趋势图）
--   studio_quiz_question         12 道新题：Java / Vue 两本教材，单选/多选/停用
--   studio_quiz_answer           26 条作答：正确 / 错误 / 跳过，多个批次
--   studio_quiz_wrong            8 条错题：待复习 / 自动消解 / 手动消解
--   studio_notification          13 条通知：审核通过 / 驳回 / 评论回复 / 成员授予
--
-- ============================================================================================================
-- 三、ID 约定
-- ============================================================================================================
-- 所有测试数据主键都落在 8990000000000000000 ~ 8992099999999999999 这个保留区间内，
-- 按「5 位前缀 + 14 位序号」分表，例如：
--   89901... sys_user        89902... studio_member      89903... studio_certificate
--   89904... 成员-证书        89905... studio_project     89906... 成员-项目
--   89907... AI 会话          89908... AI 消息            89909... 知识库文档
--   89910... 知识块           89911... 考勤               89912... 帖子
--   89913... 评论             89914... 举报               89915... 点赞
--   89916... 页面访问         89917... 刷题题目           89918... 作答记录
--   89919... 错题本           89920... 站内通知
-- 这样重跑时只要按区间清理即可，绝不会误删真实雪花 ID（真实 ID 当前在 2.1e18 量级）。
-- ============================================================================================================

SET NAMES utf8mb4;
USE `studio_db`;

START TRANSACTION;

-- ============================================================================================================
-- 四、重置旧数据（先子后父；没有外键约束，顺序只为语义清晰）
-- ============================================================================================================
-- 为什么用 DELETE 而不是 TRUNCATE：
--   TRUNCATE 属于 DDL、会隐式提交，无法放进事务整体回滚；DELETE 可以，
--   脚本中途出错时不会留下「删了一半、插了一半」的半成品数据。
-- 为什么 WHERE id > 0：
--   部分客户端（如 Workbench）默认开启 safe updates，不带主键条件的 DELETE 会被拒绝；
--   加上主键条件既满足安全模式，又等价于清空全表。
DELETE FROM `studio_notification` WHERE `id` > 0;
DELETE FROM `studio_quiz_wrong` WHERE `id` > 0;
DELETE FROM `studio_quiz_answer` WHERE `id` > 0;
-- 只删本脚本写入的 12 道题，保留题库中已有的 447 道《中国近现代史纲要》题
DELETE FROM `studio_quiz_question` WHERE `id` BETWEEN 8990000000000000000 AND 8992099999999999999;
DELETE FROM `studio_page_visit` WHERE `id` > 0;
DELETE FROM `studio_post_like` WHERE `id` > 0;
DELETE FROM `studio_post_report` WHERE `id` > 0;
DELETE FROM `studio_post_comment` WHERE `id` > 0;
DELETE FROM `studio_post` WHERE `id` > 0;
DELETE FROM `studio_attendance` WHERE `id` > 0;
DELETE FROM `studio_knowledge_chunk` WHERE `id` > 0;
DELETE FROM `studio_knowledge_doc` WHERE `id` > 0;
DELETE FROM `studio_ai_message` WHERE `id` > 0;
DELETE FROM `studio_ai_session` WHERE `id` > 0;
DELETE FROM `studio_member_project` WHERE `id` > 0;
DELETE FROM `studio_member_certificate` WHERE `id` > 0;
DELETE FROM `studio_project` WHERE `id` > 0;
DELETE FROM `studio_certificate` WHERE `id` > 0;
DELETE FROM `studio_member` WHERE `id` > 0;
DELETE FROM `sys_user` WHERE `id` > 0;

