-- ============================================================================================================
-- 十、项目案例（studio_project）
-- ============================================================================================================
-- tech_stack 是 JSON 数组快照，后端 ProjectVO 会反序列化成 List<String>，必须写合法 JSON。
INSERT INTO `studio_project`
(`id`, `title`, `cover_image`, `description`, `content`, `tech_stack`, `demo_url`, `github_url`, `leader_id`, `status`, `sort_order`, `created_at`, `updated_at`, `created_by`, `updated_by`, `deleted_at`)
VALUES
(8990500000000000001, '润石工作室官网', @img_project_1,
 '工作室对外门户，集项目展示、荣誉墙、技术博客、刷题系统与 AI 问答于一体。',
 '# 润石工作室官网\n\n官网是工作室的对外窗口，覆盖工作室介绍、项目案例、荣誉证书、技术博客、刷题系统与 AI 问答。\n\n## 核心模块\n\n- 项目与荣誉展示\n- 帖子发布与审核\n- 成员考勤\n- 刷题与错题本\n- RAG 知识问答\n\n## 技术架构\n\n前端 Vue 3 + Vite，后端 Spring Boot + MyBatis-Plus，数据层 MySQL + Redis，部署使用 Nginx 与 Docker。',
 '["Spring Boot","MyBatis-Plus","MySQL","Redis","Vue 3","Element Plus"]', 'https://runshi.example.com', 'https://github.com/runshi-studio/runshi-studio-web', 8990200000000000001, 1, 100, '2025-10-01 10:00:00', '2026-10-01 10:00:00', 1, 1, 0),
(8990500000000000002, '智慧刷题与错题本系统', @img_project_2,
 '面向课程复习的在线刷题系统，支持顺序、随机、错题三种模式，并自动维护错题本。',
 '# 智慧刷题与错题本系统\n\n系统把题目、选项与正确答案统一存放在题目表中，作答记录只追加、不修改，错题本则维护连对进度与消解状态。\n\n## 主要能力\n\n- 顺序刷题、随机抽题、错题重刷\n- 单选与多选自动判定\n- 连续答对两次自动消解\n- 按教材与章节统计正确率',
 '["Spring Boot","MyBatis-Plus","MySQL","Redis","Sa-Token"]', 'https://quiz.example.com', 'https://github.com/runshi-studio/smart-quiz', 8990200000000000002, 1, 90, '2025-11-15 10:00:00', '2026-09-20 10:00:00', 1, 1, 0),
(8990500000000000003, '校园 AI 知识问答助手', @img_project_3,
 '基于 RAG 的校园知识问答助手，把项目、成员与证书资料变成可检索、可溯源的知识库。',
 '# 校园 AI 知识问答助手\n\n助手先对业务资料做切分与向量化，用户提问时检索最相关的片段，再交给大模型生成答案，并在响应中返回引用来源。\n\n## 关键设计\n\n- 内容哈希去重，未变化的文档跳过重建\n- 向量化与写库分离，失败不影响旧索引\n- 引用来源可回溯到原始业务数据',
 '["Spring Boot","LangChain4j","阿里云百炼","Redis","Vue 3"]', 'https://ai.example.com', 'https://github.com/runshi-studio/campus-rag', 8990200000000000004, 1, 85, '2026-03-01 10:00:00', '2026-10-10 10:00:00', 1, 1, 0),
(8990500000000000004, '工作室考勤与协作看板', @img_project_4,
 '工作室日常考勤与协作看板，展示当日出勤、月度签到次数与内外网签到分布。',
 '# 工作室考勤与协作看板\n\n看板按天展示在队成员的签到情况，并统计月度签到次数。\n\n## 功能\n\n- 一键签到\n- 今日出勤看板\n- 月度签到统计\n- 内外网签到判定\n\n后续计划增加任务看板与周报汇总。',
 '["Vue 3","TypeScript","Element Plus","ECharts"]', 'https://board.example.com', 'https://github.com/runshi-studio/attendance-board', 8990200000000000006, 1, 75, '2026-04-10 10:00:00', '2026-09-30 10:00:00', 1, 1, 0),
(8990500000000000005, '校园二手交易平台', @img_project_5,
 '面向校内学生的二手物品交易平台，支持发布、搜索、收藏与站内沟通。',
 '# 校园二手交易平台\n\n项目正在研发中，当前已完成商品发布、分类搜索与收藏功能。\n\n## 下一阶段\n\n- 站内消息\n- 交易评价\n- 违规商品审核\n- 小程序端适配',
 '["Spring Boot","uni-app","MySQL","Redis"]', 'https://market.example.com', 'https://github.com/runshi-studio/campus-market', 8990200000000000007, 0, 60, '2026-08-01 10:00:00', '2026-10-18 10:00:00', 1, 1, 0),
(8990500000000000006, '数据可视化大屏', @img_project_6,
 '把工作室的访问量、项目活跃度与学习数据汇总成一块可视化大屏。',
 '# 数据可视化大屏\n\n大屏项目已结题，主要用来展示官网访问趋势、项目分布与成员学习数据。\n\n## 产出\n\n- 访问趋势折线图\n- 项目状态分布\n- 证书级别与类型统计\n- 刷题正确率排行',
 '["Vue 3","ECharts","DataV","TypeScript"]', 'https://screen.example.com', 'https://github.com/runshi-studio/data-screen', 8990200000000000005, 2, 50, '2025-12-01 10:00:00', '2026-06-30 10:00:00', 1, 1, 0);

