INSERT INTO `studio_knowledge_chunk`
(`id`, `doc_id`, `chunk_index`, `content`, `embedding_id`, `created_at`, `updated_at`, `created_by`, `updated_by`, `deleted_at`)
VALUES
(8991000000000000001, 8990900000000000001, 0, '润石工作室是信息学院下的学生软件开发团队，现设 Java 后端、前端开发、AI 应用与测试运维四个方向。工作室位于信息楼 A305，日常以项目制方式协作。', 'seed-embed-doc1-0', '2026-09-15 10:01:00', '2026-09-15 10:01:00', 1, 1, 0),
(8991000000000000002, 8990900000000000001, 1, '加入工作室需要先填写招新报名表，参加基础能力面试，再进入为期两周的新人训练营。训练营期间会完成一个小型全栈项目，双向选择后正式入队。', 'seed-embed-doc1-1', '2026-09-15 10:01:00', '2026-09-15 10:01:00', 1, 1, 0),
(8991000000000000003, 8990900000000000001, 2, '工作室每周三晚举行技术分享会，每月进行一次项目复盘。成员可以使用工作室的服务器、开发板和图书资源，也可以申请参加学科竞赛与创新创业项目。', 'seed-embed-doc1-2', '2026-09-15 10:01:00', '2026-09-15 10:01:00', 1, 1, 0),
(8991000000000000004, 8990900000000000002, 0, '润石工作室官网是工作室的对外门户，包含首页、项目案例、荣誉墙、技术博客、刷题系统和 AI 问答等模块。前端使用 Vue 3 与 Element Plus，后端使用 Spring Boot 与 MyBatis-Plus。', 'seed-embed-doc2-0', '2026-10-01 10:11:00', '2026-10-01 10:11:00', 1, 1, 0),
(8991000000000000005, 8990900000000000002, 1, '官网采用前后端分离架构，Nginx 负责静态资源与反向代理，MySQL 存储业务数据，Redis 承担登录会话、限流计数与 AI 提问计数。部署流程通过 GitHub Actions 与 Docker 完成。', 'seed-embed-doc2-1', '2026-10-01 10:11:00', '2026-10-01 10:11:00', 1, 1, 0),
(8991000000000000006, 8990900000000000003, 0, '邵兴，2022 级软件工程专业，润石工作室队长，技术方向为 Java 后端与系统架构。曾参与工作室官网、智慧刷题系统等项目，负责后端架构设计与团队协作。', 'seed-embed-doc3-0', '2026-10-01 10:21:00', '2026-10-01 10:21:00', 1, 1, 0);

-- ============================================================================================================
-- 十四、考勤签到（studio_attendance）
-- ============================================================================================================
-- 用递归 CTE 生成「最近 16 天 × 7 位在队成员」的签到记录，再过滤掉周末与 3 天请假：
--   - 相对 CURDATE() 生成，保证无论哪天执行，考勤看板与月度统计都有近期数据；
--   - 每位成员每天只签一次，attendance_date 与 check_in_at 同源；
--   - k=6（孙浩）每 4 天出现一次外网签到，用于验证 in_lan 两种取值。
-- 生成的 id = 8991100000000000000 + 天序号 × 10 + 成员序号，重跑不会与其它数据冲突。
INSERT INTO `studio_attendance`
(`id`, `user_id`, `attendance_date`, `check_in_at`, `in_lan`, `ip`, `user_agent`, `created_at`, `updated_at`, `created_by`, `updated_by`, `deleted_at`)
WITH RECURSIVE
    days AS (
        SELECT 0 AS i
        UNION ALL
        SELECT i + 1 FROM days WHERE i < 15
    ),
    members AS (
        SELECT 0 AS k, 8990100000000000001 AS user_id, '192.168.1.11' AS ip
        UNION ALL SELECT 1, 8990100000000000002, '192.168.1.12'
        UNION ALL SELECT 2, 8990100000000000003, '192.168.1.13'
        UNION ALL SELECT 3, 8990100000000000004, '192.168.1.14'
        UNION ALL SELECT 4, 8990100000000000005, '192.168.1.15'
        UNION ALL SELECT 5, 8990100000000000006, '192.168.1.16'
        UNION ALL SELECT 6, 8990100000000000007, '192.168.1.17'
    )
SELECT
    8991100000000000000 + days.i * 10 + members.k,
    members.user_id,
    DATE(DATE_ADD(DATE_SUB(CURDATE(), INTERVAL 15 DAY), INTERVAL days.i DAY)),
    DATE_ADD(DATE_ADD(DATE_SUB(CURDATE(), INTERVAL 15 DAY), INTERVAL days.i DAY), INTERVAL (540 + members.k * 6 + MOD(days.i * 13, 17)) MINUTE),
    CASE WHEN members.k = 6 AND MOD(days.i, 4) = 0 THEN 0 ELSE 1 END,
    CASE WHEN members.k = 6 AND MOD(days.i, 4) = 0 THEN '10.20.30.40' ELSE members.ip END,
    'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0 Safari/537.36',
    DATE_ADD(DATE_ADD(DATE_SUB(CURDATE(), INTERVAL 15 DAY), INTERVAL days.i DAY), INTERVAL (540 + members.k * 6 + MOD(days.i * 13, 17)) MINUTE),
    DATE_ADD(DATE_ADD(DATE_SUB(CURDATE(), INTERVAL 15 DAY), INTERVAL days.i DAY), INTERVAL (540 + members.k * 6 + MOD(days.i * 13, 17)) MINUTE),
    members.user_id,
    members.user_id,
    0
FROM days
CROSS JOIN members
WHERE DAYOFWEEK(DATE_ADD(DATE_SUB(CURDATE(), INTERVAL 15 DAY), INTERVAL days.i DAY)) NOT IN (1, 7)
  AND NOT (members.k = 2 AND days.i = 5)
  AND NOT (members.k = 4 AND days.i = 9)
  AND NOT (members.k = 6 AND days.i = 12);

