-- ============================================================================================================
-- 十八、帖子点赞（studio_post_like，物理删除表，只有 4 列）
-- ============================================================================================================
-- 根据「帖子序号 + 起止用户序号」批量生成，保证点赞行数与 post.like_count 完全一致：
--   P1: 1-12（12 个）  P2: 1-9（9 个）   P3: 1-7（7 个）   P4: 1-6（6 个）
--   P5: 2-6（5 个）    P6: 1-4（4 个）   P7: 1-8（8 个）   P8: 1-6（6 个）
INSERT INTO `studio_post_like` (`id`, `post_id`, `user_id`, `created_at`)
WITH RECURSIVE
    user_seq AS (
        SELECT 1 AS i
        UNION ALL
        SELECT i + 1 FROM user_seq WHERE i < 12
    ),
    like_plan AS (
        SELECT 1 AS post_seq, 8991200000000000001 AS post_id, 1 AS u_start, 12 AS u_end
        UNION ALL SELECT 2, 8991200000000000002, 1, 9
        UNION ALL SELECT 3, 8991200000000000003, 1, 7
        UNION ALL SELECT 4, 8991200000000000004, 1, 6
        UNION ALL SELECT 5, 8991200000000000005, 2, 6
        UNION ALL SELECT 6, 8991200000000000006, 1, 4
        UNION ALL SELECT 7, 8991200000000000007, 1, 8
        UNION ALL SELECT 8, 8991200000000000008, 1, 6
    )
SELECT
    8991500000000000000 + like_plan.post_seq * 100 + user_seq.i,
    like_plan.post_id,
    8990100000000000000 + user_seq.i,
    DATE_ADD('2026-10-10 10:00:00', INTERVAL (like_plan.post_seq + user_seq.i) HOUR)
FROM like_plan
JOIN user_seq ON user_seq.i BETWEEN like_plan.u_start AND like_plan.u_end;

-- ============================================================================================================
-- 十九、门户访问记录（studio_page_visit，只增不改不删）
-- ============================================================================================================
-- 生成最近 30 天 × 每天 8 次访问，共 240 条：
--   - 页面按 10 个常见路径轮换；
--   - 60 个 visitor_id 轮换，保证 UV 去重有意义；
--   - 部分访问关联登录用户，其余为游客（user_id = NULL）；
--   - 设备类型 pc / mobile 交替，来源域名只在部分访问上出现。
INSERT INTO `studio_page_visit`
(`id`, `page_path`, `visitor_id`, `user_id`, `referrer_host`, `device_type`, `created_at`, `created_by`)
WITH RECURSIVE seq AS (
    SELECT 0 AS n
    UNION ALL
    SELECT n + 1 FROM seq WHERE n < 239
)
SELECT
    8991600000000000000 + seq.n,
    ELT(MOD(seq.n, 10) + 1,
        '/', '/projects', '/certificates', '/posts', '/quiz',
        '/ai-chat', '/workspace', '/notifications',
        CONCAT('/projects/', 8990500000000000001),
        CONCAT('/posts/', 8991200000000000001)),
    CONCAT('visitor-', LPAD(MOD(seq.n * 7, 60) + 1, 4, '0')),
    CASE
        WHEN MOD(seq.n, 5) = 0 THEN 8990100000000000001
        WHEN MOD(seq.n, 7) = 0 THEN 8990100000000000002
        WHEN MOD(seq.n, 11) = 0 THEN 8990100000000000009
        ELSE NULL
    END,
    CASE
        WHEN MOD(seq.n, 9) = 0 THEN 'www.baidu.com'
        WHEN MOD(seq.n, 13) = 0 THEN 'github.com'
        WHEN MOD(seq.n, 17) = 0 THEN 'weixin.qq.com'
        ELSE NULL
    END,
    CASE WHEN MOD(seq.n, 3) = 0 THEN 'mobile' ELSE 'pc' END,
    DATE_ADD(
        DATE_ADD(DATE_SUB(CURDATE(), INTERVAL 29 DAY), INTERVAL (seq.n DIV 8) DAY),
        INTERVAL (480 + MOD(seq.n, 12) * 30 + MOD(seq.n * 7, 30)) MINUTE
    ),
    0
FROM seq;

